INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Ping nur für IPv6-Netze geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Funktioniert auch mit IPv4"}, {"text": "Ja", "correct": false, "because": "Protokollunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt Ping in IPv6?', 3, '[{"text": "ICMPv6", "correct": true, "because": "Echo Request/Reply"}, {"text": "TCP", "correct": false, "because": "Transportebene"}, {"text": "UDP", "correct": false, "because": "Nicht für Erreichbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen hat Ping?', 5, '[{"text": "Erreichbarkeit prüfen", "correct": true, "because": "Testet Antwort"}, {"text": "Latenz messen", "correct": true, "because": "Zeigt Verzögerung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht Ping-Aufgabe"}, {"text": "IP zuweisen", "correct": false, "because": "DHCP-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ping nutzt ICMPv6. b) Es läuft auf Schicht 4.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 3, nicht 4"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Ping?', 4, '[{"text": "Echo Request", "correct": false, "because": "Kern der Anfrage"}, {"text": "Zieladresse", "correct": false, "because": "Definiert Empfänger"}, {"text": "Datenpayload", "correct": true, "because": "Nur Diagnose, kein Inhalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ping eine Antwort garantiert?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Netz und Firewall"}, {"text": "Ja", "correct": false, "because": "Keine Garantie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht sende ich mit Ping?', 3, '[{"text": "Echo Request", "correct": true, "because": "Fordert Reply an"}, {"text": "Neighbor Solicitation", "correct": false, "because": "NDP-spezifisch"}, {"text": "Router Advertisement", "correct": false, "because": "SLAAC-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen liefert Ping?', 5, '[{"text": "Rundlaufzeit", "correct": true, "because": "Misst Latenz"}, {"text": "Paketverlust", "correct": true, "because": "Zeigt Zuverlässigkeit"}, {"text": "Bandbreitengrenze", "correct": false, "because": "Andere Tools"}, {"text": "DNS-Name", "correct": false, "because": "Nur IP-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ping nutzt ICMPv6 in IPv6. b) Es verschlüsselt Daten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Verschlüsselung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Ping?', 4, '[{"text": "Ziel-IP", "correct": false, "because": "Definiert Empfänger"}, {"text": "ICMPv6", "correct": false, "because": "Protokollbasis"}, {"text": "Webserver", "correct": true, "because": "Nicht Diagnose-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Ping in IPv6 optional?', 2, '[{"text": "Nein", "correct": true, "because": "Kernfunktion von ICMPv6"}, {"text": "Ja", "correct": false, "because": "Standard-Diagnose"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis zeigt mir, dass ein Gerät erreichbar ist?', 4, '[{"text": "Echo Reply", "correct": true, "because": "Bestätigt Antwort"}, {"text": "Timeout", "correct": false, "because": "Zeigt Fehler"}, {"text": "Destination Unreachable", "correct": false, "because": "Problem im Netz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Ping nur Latenz misst. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Erreichbarkeit"}, {"text": "Ja", "correct": false, "because": "Mehr als nur Latenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Ping?', 3, '[{"text": "Zieladresse", "correct": true, "because": "Definiert Testziel"}, {"text": "Paketgröße", "correct": false, "because": "Sekundär"}, {"text": "Protokolltyp", "correct": false, "because": "ICMPv6 Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ping testet Erreichbarkeit. b) Es nutzt TCP.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ICMPv6, nicht TCP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Ping?', 5, '[{"text": "Schnelle Diagnose", "correct": true, "because": "Testet Erreichbarkeit"}, {"text": "Latenzmessung", "correct": true, "because": "Zeigt Verzögerung"}, {"text": "Datenübertragung", "correct": false, "because": "Nur Diagnose"}, {"text": "IP-Konfiguration", "correct": false, "because": "Andere Tools"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Ping unwichtig?', 3, '[{"text": "Echo Reply", "correct": false, "because": "Bestätigt Erreichbarkeit"}, {"text": "Ziel-IP", "correct": false, "because": "Definiert Empfänger"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft Ping über UDP?', 3, '[{"text": "Nein", "correct": true, "because": "ICMPv6 direkt"}, {"text": "Ja", "correct": false, "because": "Verwechselt Protokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ping Paketverlust zeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Prozentual angezeigt"}, {"text": "Nein", "correct": false, "because": "Teil der Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Antwort erwartest du bei einem erfolgreichen Ping?', 4, '[{"text": "Echo Reply", "correct": true, "because": "Bestätigt Erreichbarkeit"}, {"text": "Time Exceeded", "correct": false, "because": "Fehleranzeige"}, {"text": "Neighbor Advertisement", "correct": false, "because": "NDP-spezifisch"}]');
